226→        let errors = validate_config(&config);
227→        assert!(errors.iter().any(|e| e.rule == "unknown-workflow-step"));
228→    }
229→
230→    #[test]
231→    fn detects_circular_dependency() {
232→        let mut config = BivvyConfig::default();
233→
234→        let step_a = StepConfig {
235→            command: Some("a".to_string()),
236→            depends_on: vec!["b".to_string()],
237→            ..Default::default()
238→        };
239→
240→        let step_b = StepConfig {
241→            command: Some("b".to_string()),
242→            depends_on: vec!["a".to_string()],
243→            ..Default::default()
244→        };
245→
246→        config.steps.insert("a".to_string(), step_a);
247→        config.steps.insert("b".to_string(), step_b);
248→
249→        let errors = validate_config(&config);
250→        assert!(errors.iter().any(|e| e.rule == "circular-dependency"));
251→    }
252→
253→    #[test]
254→    fn valid_config_returns_no_errors() {
255→        let mut config = BivvyConfig::default();
256→
257→        let step_a = StepConfig {
258→            command: Some("a".to_string()),
259→            ..Default::default()
260→        };
261→
